"use strict";(self.webpackChunkchzhshch_blog=self.webpackChunkchzhshch_blog||[]).push([["59966"],{71532(e,n,t){t.d(n,{Ay:()=>h,RM:()=>s});var o=t(74848),a=t(28453),r=t(66422);let s=[];function i(e){let n={blockquote:"blockquote",h1:"h1",header:"header",p:"p",...(0,a.R)(),...e.components};return(0,o.jsxs)(o.Fragment,{children:[(0,o.jsx)(n.header,{children:(0,o.jsx)(n.h1,{id:"the-chen-jingrun-phenomenon-a-textbook-case-of-overblown-hype-in-a-distorted-era",children:"The Chen Jingrun Phenomenon: A Textbook Case of Overblown Hype in a Distorted Era!"})}),"\n",(0,o.jsxs)(n.blockquote,{children:["\n",(0,o.jsx)(n.p,{children:"2006/5/30 16:54:30"}),"\n"]}),"\n",(0,o.jsxs)("div",{style:{textAlign:"center"},children:[(0,o.jsx)("img",{src:(0,r.Ay)("/img/essays/chenjingrun/1.jpeg")}),(0,o.jsx)("br",{}),(0,o.jsx)("br",{})]}),"\n",(0,o.jsx)(n.p,{children:"Just came across an article on the tenth anniversary of Chen Jingrun's passing. Let me briefly discuss the Chen Jingrun phenomenon. Of course, it must be stated that the Chen Jingrun phenomenon has nothing to do with Chen Jingrun the person \u2014 he merely did something he enjoyed doing, which is perfectly normal. The Chen Jingrun phenomenon, however, is a freak product of an academic matter blown out of proportion in an unhealthy atmosphere."}),"\n",(0,o.jsx)(n.p,{children:"Only the weak need to loudly prove their strength \u2014 this is probably the common psychological distortion behind all freakish phenomena like the Chen Jingrun case. In fact, from an academic standpoint, the problem Chen Jingrun researched is not important at all in mathematics. Even by the standard of comparing among Chinese people themselves, Chen Jingrun's achievements are a hundred thousand miles behind those of his same-surnamed Chen Shiing-Shen [S.S. Chern]."}),"\n",(0,o.jsx)(n.p,{children:"From another angle: if the problem Chen Jingrun researched had been posed by the Japanese, he'd probably have been elevated to national hero. But comparing with foreign examples \u2014 anyone with basic mathematical knowledge knows that Fermat's Conjecture is far more important than the Goldbach Conjecture that Chen Jingrun researched. Without research into Fermat's Conjecture, fields like algebraic number theory, algebraic geometry, and group theory could never have reached their current heights. The complete resolution of Fermat's Conjecture mobilized many of the most important tools at the frontier of mathematics. It was one of the most glorious victories in last century's mathematics, a symbol of the dramatically increased power that came with modern mathematics' growing abstraction and structuralism. How could the Goldbach Conjecture and its ilk compare? Let alone results that were still far from a complete solution!"}),"\n",(0,o.jsx)(n.p,{children:"Furthermore, everyone knows the historical animosity between the French and English is no less than that between China and Japan, and academically they've battled for centuries. Yet when this problem posed by a Frenchman was solved centuries later by an Englishman, the honors that Englishman received in his country were incomparable to what Chen Jingrun received \u2014 what does this tell us? A nation that produced Newton, even when defeating its archrival on one of the last century's most important mathematical achievements, would not lose its composure or engage in ostentatious boasting. This is the bearing of a true cultural and academic powerhouse."}),"\n",(0,o.jsx)(n.p,{children:"When China has produced its own Newton and Einstein, phenomena like the Chen Jingrun case will probably no longer occur. Those who have never seen the ocean are the ones who boast about streams \u2014 and this too is the perfect symbol of a distorted era. Now, in an era of too many idols, it's actually equivalent to having no idols at all. Every idol is treated like a special profession, specially professionalized. Everyone can very specially professionalize the idols \u2014 and this, is the true progress of the age!"})]})}function h(e={}){let{wrapper:n}={...(0,a.R)(),...e.components};return n?(0,o.jsx)(n,{...e,children:(0,o.jsx)(i,{...e})}):i(e)}},47546(e,n,t){t.r(n),t.d(n,{metadata:()=>o,default:()=>u,frontMatter:()=>i,contentTitle:()=>h,toc:()=>c,assets:()=>l});var o=JSON.parse('{"id":"essays/chenjingrun","title":"","description":"","source":"@site/i18n/en/docusaurus-plugin-content-docs/current/essays/chenjingrun.md","sourceDirName":"essays","slug":"/essays/chenjingrun","permalink":"/en/essays/chenjingrun","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"id":"chenjingrun","title":"","hide_table_of_contents":true,"sidebar_label":"The Chen Jingrun Phenomenon: A Typical Case of Overblown Hype in a Distorted Era! (2006/5/30 16:54:30)"},"sidebar":"essaysSidebar","previous":{"title":"Xu Peidong: The Face of the Mainstream! (2006/5/29 0:52:25)","permalink":"/en/essays/xupeidong"},"next":{"title":"Learn from the Good Example of Japan (2006/5/31 17:29:32)","permalink":"/en/essays/followjapan"}}'),a=t(74848),r=t(28453),s=t(71532);let i={id:"chenjingrun",title:"",hide_table_of_contents:!0,sidebar_label:"The Chen Jingrun Phenomenon: A Typical Case of Overblown Hype in a Distorted Era! (2006/5/30 16:54:30)"},h,l={},c=[...s.RM];function d(e){return(0,a.jsx)(s.Ay,{})}function u(e={}){let{wrapper:n}={...(0,r.R)(),...e.components};return n?(0,a.jsx)(n,{...e,children:(0,a.jsx)(d,{...e})}):d(e)}},28453(e,n,t){t.d(n,{R:()=>s,x:()=>i});var o=t(96540);let a={},r=o.createContext(a);function s(e){let n=o.useContext(r);return o.useMemo(function(){return"function"==typeof e?e(n):{...n,...e}},[n,e])}function i(e){let n;return n=e.disableParentContext?"function"==typeof e.components?e.components(a):e.components||a:s(e.components),o.createElement(r.Provider,{value:n},e.children)}}}]);